-- 循環溶媒の物質収支と追加費用。変更前指紋を検査し一度だけ適用。
begin;
select set_config('amd.cost_change_reason','まさ指示: 少量溶媒の循環回収へ再試算、脂肪酸分泌の菌体性能リスクを明示',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b5c360dd3b9166b844165dc87d8ce99b' then raise exception 'fuel changed: models'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from '35e41b09de253218b199846bccdbe027' then raise exception 'fuel changed: assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b80c6219e74a52ef6ace596640168f64' then raise exception 'fuel changed: items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from '482096022c7df05d66d1fc332098d127' then raise exception 'fuel changed: tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b0990a289484c9ccb05f06253e7812d9' then raise exception 'fuel changed: notes'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '0fcd1c6c7f000ab8d00d11ac4f1396d2' then raise exception 'effluent changed'; end if;
end $$;
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_mode','cm_p21_fuel_260914',null,'溶媒の循環回収','溶媒の回収方式',null,'loop',null,'H','仮置き','AMD（内部）',true,'fuel_solvent_mode','循環回収は接触→アルカリへの移行→再生溶媒の返送を行う設計仮説。SOL株・運転条件での連続実証は未実施。全槽保持の比較へ切替可能。','amd_internal',150,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_overlay_percent','cm_p21_fuel_260914',null,'溶媒の循環回収','全槽で保持する溶媒の体積比率',5,null,'%','H','仮置き','AMD（内部）',true,'fuel_solvent_overlay_percent','全槽保持の旧比較仮定。培養液に対する5%を必須とする実測根拠はない。現在の液量と溶媒価格から開始資金を再計算する。','amd_internal',151,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_net_loading','cm_p21_fuel_260914',null,'溶媒の循環回収','循環1回で溶媒が受け取る脂肪酸',0.8,null,'kg/m³','H','仮置き','AMD（内部）',true,'fuel_solvent_net_loading','濃い側1.0−再生後0.2＝正味0.8kg/m³を設計用に仮置き。Kato2017の0.40g/Lは培養液あたりの回収量。培養液50mL/溶媒20mLなので溶媒そのものでは約1.0g/L。これは蓄積濃度で、正味0.8の連続抽出性能を実証した値ではない。温度・pH・脂肪酸組成・塩・界面面積で測定する。','amd_internal',152,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_cycle_minutes','cm_p21_fuel_260914',null,'溶媒の循環回収','溶媒が循環・再生を一巡する時間',30,null,'分','H','仮置き','AMD（内部）',true,'fuel_solvent_cycle_minutes','接触・アルカリ移行・相分離・配管を含め30分を内部仮置き。必要溶媒m³＝毎時循環量×一巡時間/60＋予備量。滞留が長くなると必要資金も増える。','amd_internal',153,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_buffer_m3','cm_p21_fuel_260914',null,'溶媒の循環回収','溶媒の予備・最低保持量',2,null,'m³','H','仮置き','AMD（内部）',true,'fuel_solvent_buffer_m3','配管充填・液面維持・予備を合計2m³で仮置き。必要在庫は循環分にこれを加え、生産0のときは0。','amd_internal',154,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_hours_day','cm_p21_fuel_260914',null,'溶媒の循環回収','循環回収の運転時間',12,null,'時間/日','H','仮置き','AMD（内部）',true,'fuel_solvent_hours_day','年の稼働日数と掛けて毎時流量を求める。日中12時間を仮置き。間欠生産・夜間の蓄積・起動停止時の濃度は実測する。','amd_internal',155,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_density','cm_p21_fuel_260914',null,'溶媒の循環回収','回収溶媒の密度',900,null,'kg/m³','H','仮置き','AMD（内部）',true,'fuel_solvent_density','旧予算とそろえた0.9t/m³の保守的な仮定。実溶媒・温度で更新。買値は溶媒補給の明細の500円/kgを参照する。','amd_internal',156,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_loss_percent','cm_p21_fuel_260914',null,'溶媒の循環回収','循環1回ごとの溶媒の損失率',0.005,null,'%','H','仮置き','AMD（内部）',true,'fuel_solvent_loss_percent','旧モデルの0.005%/通過を未実測Hとして保持し、循環溶媒m³×密度×損失率から年間補給kgを再計算。必要在庫を減らすだけで消耗費を0にはしない。持出し・乳化・吸着・劣化・洗浄時の廃棄を測定する。','amd_internal',157,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_water_drop','cm_p21_fuel_260914',null,'溶媒の循環回収','培養液の1回通過で回収する脂肪酸濃度差',20,null,'mg/L','H','仮置き','AMD（内部）',true,'fuel_solvent_water_drop','水側の入口34→出口14mg/L相当の差20mg/Lを設計仮置き。Kato2017の水側34mg/Lは他株・他条件の蓄積値で、SOLの安全閾値ではない。必要な培養液送液量＝脂肪酸kg/年÷濃度差kg/m³。入口から出口までの実際の移動量を測定する。','amd_internal',158,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_water_power','cm_p21_fuel_260914',null,'溶媒の循環回収','培養液の送液・前ろ過の電力',0.01,null,'kWh/m³','H','仮置き','AMD（内部）',true,'fuel_solvent_water_power','20kPa・効率60%で0.00926kWh/m³を0.01へ丸めた内部仮定。大型の側流送液を含む。膜の差圧・汚れ・遠距離配管が増えれば上方修正する。','amd_internal',159,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_organic_power','cm_p21_fuel_260914',null,'溶媒の循環回収','溶媒を循環・送液する電力',0.03,null,'kWh/m³','H','仮置き','AMD（内部）',true,'fuel_solvent_organic_power','50kPa・効率55%で0.0253kWh/m³を0.03へ丸めた内部仮定。電力買値は既存の回収電力明細17.45円/kWhから取得。','amd_internal',160,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_strip_power','cm_p21_fuel_260914',null,'溶媒の循環回収','アルカリ移行・混合・分離の電力',0.5,null,'kWh/kg-脂肪酸','H','仮置き','AMD（内部）',true,'fuel_solvent_strip_power','送液とは別の再生混合・分離を0.5kWh/kgで内部仮置き。既存の回収電力1.0kWh/kgは循環方式では0へし、この欄と水/溶媒送液から一度計算。加温・薬品は従来の明細を維持する。','amd_internal',161,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_loop_capex','cm_p21_fuel_260914',null,'溶媒の循環回収','循環回収の追加装置総額',15000000,null,'円','H','仮置き','AMD（内部）',true,'fuel_solvent_loop_capex','内部予算1500万円。接触部600万、連続再生/相分離部400万、循環受槽・配管・制御据付500万。既存培養槽・酸析槽・FAME転換の再購入は含まない。基準条件の培養液約1525m³/h・溶媒約38m³/hに対応する装置の供給者見積/物質移動性能は未取得。膜なら必要面積・交換費、直接接触なら菌体への毒性と乳化を確認する。','amd_internal',162,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_loop_life','cm_p21_fuel_260914',null,'溶媒の循環回収','循環回収装置の耐用年数',7,null,'年','H','仮置き','AMD（内部）',true,'fuel_solvent_loop_life','内部比較用7年。新しい循環装置だけの償却。既存設備の参考CAPEXを自動で購入しない。','amd_internal',163,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_loop_annual','cm_p21_fuel_260914',null,'溶媒の循環回収','循環回収で増える保守・交換費',450000,null,'円/年','H','仮置き','AMD（内部）',true,'fuel_solvent_loop_annual','追加装置1500万円の3%/年の内部予算。ポンプ/シール/接触部の消耗・外注保守を想定。作業の追加人時、既存回収の部品年30万円、送気前処理、分析維持と区分。膜を採る場合の交換量・洗浄頻度は見積で更新する。','amd_internal',164,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_loop_funding_rate','cm_p21_fuel_260914',null,'溶媒の循環回収','初回溶媒の年資金コスト（比較用）',3,null,'%/年','H','仮置き','AMD（内部）',true,'fuel_solvent_funding_rate','開始時に保持する溶媒資金へ年3%を掛けて原価へ加算。借入合意ではなく比較用。0へ変更可能。設備投資の資金調達費・税・本社共通費は別。元本を年間費用へ二重計上しない。','amd_internal',165,null,null);
update project_cost_items set note='旧比較の係数0.11kg/kg-脂肪酸はHとして保持。循環回収時は、この行の買値500円/kgを参照し、正味濃度差・密度・1回あたり損失率から補給量を別計算する。Kato2017の溶媒相0.40g/Lという表示は培養液あたりの量で、溶媒自体は約1.0g/L。溶媒濃度0.40を根拠にした従来の必要循環量約2.4m³/kgは採用しない。0.005%の損失は未測定。',updated_at=now() where cost_item_id='cif_sec_solvent_makeup' and cost_model_id='cm_p21_fuel_260914';
update project_cost_items set note='全槽保持の比較では従来の回収電力1.0kWh/kg-脂肪酸を保持。循環回収時は、この行の電力買値17.45円/kWhを使い、培養液送液量×動力原単位＋溶媒循環量×動力原単位＋脂肪酸kg×再生混合分離原単位から別計算する。培養液の送液・前ろ過を含む。Kato2017の0.40g/Lは培養液基準で、溶媒自身の濃度ではない。',updated_at=now() where cost_item_id='cif_sec_op_power' and cost_model_id='cm_p21_fuel_260914';
update project_cost_items set note='全槽保持の旧参考。現在は開始資金を回収方式に応じて計算する。循環回収では流量×一巡時間＋予備量、全槽保持比較では培養液量×保持比率で必要m³を算出し、溶媒補給明細の買値と密度を掛ける。設備償却と年間消耗補給はそれぞれ別。',updated_at=now() where cost_item_id='cif_sec_solvent_fill' and cost_model_id='cm_p21_fuel_260914';
insert into project_cost_tasks (note,label,owner,strain,scenario,performer,confidence,format_row,sort_order,visibility,application,group_label,hourly_rate,source_kind,cost_task_id,count_driver,cost_model_id,count_per_year,hours_per_occurrence,expense_per_occurrence) values ('循環接触部・再生部・配管の追加点検清掃を月1回2人時で内部仮置き。循環回収のときだけ計上。部品/外注保守は循環回収の年額45万円と区分。実測・膜交換の頻度で更新する。','循環回収で増える点検・清掃（1回）','AMD（内部）',null,'共通','sx','H',null,37,'amd_internal',null,'追加保守・異常対応',null,'仮置き','ctf_solvent_loop_maintenance','fixed','cm_p21_fuel_260914',12,2,0);
update project_cost_notes set title='循環回収の実証条件',body_md='少量の溶媒を循環・再生して脂肪酸を取り出す設計。必要在庫は回収量・正味の濃度差・循環再生の一巡時間で決める。追加接触/再生装置・送液電力・溶媒損失・保守・追加人時・初回溶媒の資金コストも加算する。既存培養・FAME設備の利用は共用できる仮定。菌体の光合成と排水処理能力の維持を実測する。' where cost_note_id='cnf_caveat_line' and cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='分泌と回収による菌体への影響',body_md='脂肪酸の細胞内蓄積と培養液への蓄積は、膜や光合成へ障害を起こしうる。Kato2017では製品の抽出で細胞内蓄積が減り光合成指標が改善したが、SOL株の排水処理能力を測定した結果ではない。溶媒への接触、炭素・還元力の分配、細胞表面の変化、回収後の脂肪酸/溶媒持出しを確認する。' where cost_note_id='cnf_caveat_biomass' and cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='513時点：全槽5%保持・資金コスト前の比較（履歴）',body_md='2026-10-17保存条件の基準収率・排ガス・太陽光・自社日常分析ではFAME年106744.6L、自社転換200.64円/L、売価200円/Lに対して年6.85万円の赤字（資金調達費・税・本社共通費前）。委託262.52円/L。見積幅の比較は自社192.01～222.59円/Lで黒字を確認したとはいえない。既存FAME能力を使えず参考500万円/系列×6系列を追加購入し保守3%/年を足すと249.22円/L。回収装置を新規購入する分はこの比較にも別途必要。初回溶媒4.57億円に仮の資金コスト3%をかけると自社329.22円/L。開始資金と年間補給費は二重計上していない。排水量を約9.37%へ下げFAME年10000Lになる比較では、同じ設備予算・固定費を残して送気電力70万円分と初回溶媒を比例縮小すると562.19円/L、年362.2万円赤字、初回溶媒4285.8万円。これは小型化した設備の見積ではない。数量は排水事業の菌体使用量からの出力で、燃料年産の手入力には戻さない。各比較はここに記載した保存条件の記録で、画面で条件を変えた結果は右側の再計算を参照する。' where cost_note_id='cnf_est_viability_261017' and cost_model_id='cm_p21_fuel_260914';
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_loop_research_261017','cm_p21_fuel_260914','benchmark','循環回収の根拠と濃度の基準','Kato2017は培養液50mLにIM20mLを重ねる小規模試験。240hで溶媒相の回収量0.40g/L-培養液、水側0.034g/L。溶媒自身の濃度は0.40×50/20＝約1.0g/L。連続回収の正味濃度差0.8kg/m³と一巡30分は設計仮定。JoVE2024は中鎖脂肪酸を二つの中空糸接触器とアルカリ水で連続抽出・逆抽出する実験を報告している。SOLの長鎖脂肪酸・溶媒・培養条件への転用は物質移動、乳化、膜汚れ、菌体影響の検証が必要。技術方式には先行例があり、SOLでの性能は未測定。連続抽出: https://www.jove.com/t/66956/continuous-liquid-liquid-extraction-medium-chain-fatty-acids-from','Kato2017と連続液液抽出の研究例','https://link.springer.com/article/10.1186/s13068-017-0831-z','amd_internal',30);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_loop_biology_261017','cm_p21_fuel_260914','caveat','油への弱さと脂肪酸分泌の性能リスク','まさからの情報として、杉浦先生は油の多い廃液で処理効率が落ちる可能性を指摘。原因と条件は未確定。外部の油は脂肪酸のほか中性脂質・鉱油・添加剤等を含み、遮光、気液接触、菌体被覆や共存物質の影響を受けうる。分泌株はさらに、細胞内の脂肪酸過剰、膜/光合成の障害、合成への炭素・還元力配分、輸送・膜修飾の影響が加わる。速い回収は外部蓄積を抑え分泌を助けるが、細胞内の輸送律速や出荷後の処理能力は個別に評価する。待ち3日を経た親株/分泌株×回収なし/循環ありで、同じ乾燥菌体量当たりの色素除去・金属除去速度、光合成指標、残存脂肪酸・溶媒、回復性を比較する。','脂肪酸の細胞内蓄積と回収による生理影響','https://link.springer.com/article/10.1186/s13068-017-0831-z','amd_internal',31);
update project_cost_models set version_label='261017 溶媒循環回収の設計試算',summary_md='出荷待ち菌体の分泌脂肪酸を少量の溶媒で循環回収する設計と、全槽で溶媒を保持する比較を切り替える。溶媒量・培養液送液量・補給・電力・追加装置・資金負担を物質収支から算出する。',system_scope_md='循環回収は接触・アルカリ移行・溶媒再生返送の設計仮説。正味濃度差0.8kg/m³、一巡30分、予備2m³、水側回収濃度差20mg/Lを内部仮置き。追加循環装置1500万円、7年償却、保守年45万円と追加点検を加える。送気・分析の前提は維持。初回溶媒資金の年3%も原価へ加算。実際の装置能力・損失・株の光合成/排水処理性能は未測定。既存培養・酸析・FAME設備を共用できる条件で、設備投資の資金調達費・税・本社共通費は別。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
do $$ begin
 if (select count(*) from project_cost_assumptions where cost_model_id='cm_p21_fuel_260914') <> 93 or (select count(*) from project_cost_tasks where cost_model_id='cm_p21_fuel_260914') <> 12 or (select count(*) from project_cost_notes where cost_model_id='cm_p21_fuel_260914') <> 29 then raise exception 'unexpected row counts'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '0fcd1c6c7f000ab8d00d11ac4f1396d2' then raise exception 'effluent changed'; end if;
end $$;
commit;
